style.css:
@-moz-document domain("spacehey.com") {
/* Background */
body {
    background-color: #ffccdd !important;
    color: #000;
}

/* Main Content */
#page {
    background-color: #ff99cc !important;
    border: 3px solid #ff6699;
    border-radius: 10px;
    padding: 10px;
}

/* Sidebar */
#left, #right {
    background-color: #ffb6c1 !important;
    border: 2px solid #ff6699;
    border-radius: 10px;
    padding: 10px;
}

/* Links */
a {
    color: #d6006d !important;
    font-weight: bold;
    text-decoration: none;
}
a:hover {
    color: #ff007f !important;
    text-decoration: underline;
}

/* Headers */
h1, h2, h3 {
    color: #ff3366 !important;
    text-shadow: 1px 1px 2px #ff6699;
}

/* Boxes and Tables */
.box, .table {
    background-color: #ffc0cb !important;
    border: 2px solid #ff6699;
    padding: 10px;
    border-radius: 10px;
}

/* Buttons */
button, input[type='submit'] {
    background-color: #ff6699 !important;
    color: #fff !important;
    border: 2px solid #d6006d;
    padding: 5px 10px;
    border-radius: 5px;
    cursor: pointer;
}
button:hover, input[type='submit']:hover {
    background-color: #ff3366 !important;
}

/* Navbar */
.nav {
    background-color: #ff80bf !important;
    border-bottom: 3px solid #ff3366;
    padding: 5px;
}

/* Friend Boxes */
.friend {
    background-color: #ffb3c6 !important;
    border: 2px solid #ff6699;
    border-radius: 10px;
    padding: 10px;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}
::-webkit-scrollbar-track {
    background: #ff99cc;
}
::-webkit-scrollbar-thumb {
    background: #ff3366;
}
}
